import React, { useEffect, useRef, ReactNode, Children, isValidElement, CSSProperties } from 'react';
import { motion, useAnimation, Variants } from 'framer-motion';
import { useAnimation as useAnimationContext, useAnimationId, AnimationProvider } from './AnimationContext';

interface AnimatedListProps {
  children: ReactNode;
  className?: string;
  staggerDelay?: number;
  staggerVariation?: number;
  animateOnMount?: boolean;
  onAnimationComplete?: () => void;
  component?: 'ul' | 'ol' | 'div';
  itemComponent?: 'li' | 'div';
}

/**
 * AnimatedList - A component that animates its children in sequence
 * with controlled timing and proper completion
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  children,
  className = '',
  staggerDelay = 0.2,
  staggerVariation = 0.1,
  animateOnMount = true,
  onAnimationComplete,
  component = 'ul',
  itemComponent = 'li'
}) => {
  // Animation state tracking
  const hasAnimatedRef = useRef(false);
  const controls = useAnimation();

  // Generate unique ID for this animation
  const animationId = useAnimationId('list');

  // Access animation context
  const { registerAnimation } = useAnimationContext();

  // Calculate randomized delays for each item
  const getRandomDelay = (index: number): number => {
    // Base stagger delay
    const baseDelay = index * staggerDelay;

    // Add randomness for organic feel
    const randomOffset = (Math.random() * 2 - 1) * staggerVariation;

    // Add occasional slightly longer pause to simulate thinking
    const thinkingPause = Math.random() > 0.8 ? 0.2 : 0;

    return baseDelay + randomOffset + thinkingPause;
  };

  // Define the animation start function
  const startAnimation = async (): Promise<void> => {
    if (hasAnimatedRef.current) return Promise.resolve();

    return new Promise<void>((resolve) => {
      controls.start("visible")
        .then(() => {
          hasAnimatedRef.current = true;
          if (onAnimationComplete) {
            onAnimationComplete();
          }
          resolve();
        })
        .catch(error => {
          console.error("Animation error:", error);
          resolve();
        });
    });
  };

  // Register this animation with the context
  useEffect(() => {
    registerAnimation(animationId, startAnimation);

    // Start animation on mount if specified
    if (animateOnMount && !hasAnimatedRef.current) {
      startAnimation();
    }

    return () => {
      controls.stop();
    };
  }, [registerAnimation, animationId, animateOnMount]);

  // List container variant
  const containerVariants: Variants = {
    hidden: {},
    visible: {
      transition: {
        when: "beforeChildren",
        staggerChildren: staggerDelay,
        delayChildren: 0,
      }
    }
  };

  // Item animation variant
  const itemVariants: Variants = {
    hidden: { 
      opacity: 0, 
      y: 3,
      height: "auto" 
    },
    visible: (index) => ({
      opacity: 1,
      y: 0,
      height: "auto",
      transition: {
        duration: 0.15,
        delay: getRandomDelay(index),
        ease: "easeOut"
      }
    })
  };

  // Define inline styles with proper TypeScript typing
  const itemStyle: CSSProperties = {
    width: '100%', 
    display: 'flex', 
    justifyContent: 'flex-start'
  };

  const listItemStyle: CSSProperties = {
    width: '100%', 
    listStyle: 'none'
  };

  const listContainerStyle: CSSProperties = {
    margin: 0,
    padding: 0,
    listStyle: 'none',
    display: 'flex',
    flexDirection: 'column' as const,
    alignItems: 'flex-start',
    width: '100%'
  };

  // Process children to add animation properties
  const animatedItems = Children.map(children, (child, index) => {
    if (!isValidElement(child)) return child;

    // For each child, wrap it in an Animation Provider to coordinate animations
    const childWithAnimation = (
      <AnimationProvider parentId={animationId}>
        <motion.div
          custom={index}
          variants={itemVariants}
          initial="hidden"
          animate={controls}
          style={itemStyle}
        >
          {child}
        </motion.div>
      </AnimationProvider>
    );

    return itemComponent === 'li' 
      ? <li key={`item-${index}`} style={listItemStyle}>{childWithAnimation}</li>
      : <div key={`item-${index}`} style={listItemStyle}>{childWithAnimation}</div>;
  });

  // Render the appropriate container element
  const listProps = {
    className: `animated-list ${className}`,
    style: listContainerStyle,
    variants: containerVariants
  };

  switch (component) {
    case 'ol':
      return <motion.ol {...listProps}>{animatedItems}</motion.ol>;
    case 'div':
      return <motion.div {...listProps}>{animatedItems}</motion.div>;
    case 'ul':
    default:
      return <motion.ul {...listProps}>{animatedItems}</motion.ul>;
  }
};

export default AnimatedList;
